import { findAndRemoveImports, getAST, stringifyTree } from '@mintlify/common';
import fse from 'fs-extra';
import { mkdtemp, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
const testPaths = vi.hoisted(() => ({ cmd: '', public: '' }));
vi.mock('../constants.js', () => ({
    get CMD_EXEC_PATH() {
        return testPaths.cmd;
    },
    get NEXT_PUBLIC_PATH() {
        return testPaths.public;
    },
}));
vi.mock('../local-preview/listener/utils.js', () => ({
    getCurrentVariables: vi.fn(async () => ({})),
    handleParseError: vi.fn(),
}));
import { resolvePageImports } from '../local-preview/listener/resolve-page-imports.js';
import { setPackageImportOptions } from '../local-preview/packages/state.js';
const PAGE = `import { LineChart } from "recharts";
import { Toggle } from "/snippets/toggle.jsx";
import { Note } from "/snippets/note.mdx";

<LineChart width={400} height={200} />

<Toggle />

<Note />
`;
const resolve = async () => {
    const importsResponse = await findAndRemoveImports(getAST(PAGE, '/page.mdx'));
    return stringifyTree(await resolvePageImports({ ...importsResponse, filename: 'page.mdx' }));
};
describe('page imports in mint dev with npm packages', () => {
    let root;
    beforeEach(async () => {
        root = await mkdtemp(join(tmpdir(), 'packages-imports-'));
        testPaths.cmd = join(root, 'docs');
        testPaths.public = join(root, 'public');
        await fse.ensureDir(testPaths.public);
        await fse.outputFile(join(testPaths.cmd, 'snippets/toggle.jsx'), 'import { Switch } from "@acme/ui";\nexport const Toggle = () => <Switch />;\n');
        await fse.outputFile(join(testPaths.cmd, 'snippets/note.mdx'), 'export const Note = () => <p>Hi</p>;\n');
        vi.spyOn(console, 'log').mockImplementation(() => { });
    });
    afterEach(async () => {
        setPackageImportOptions(undefined);
        vi.mocked(console.log).mockRestore();
        await rm(root, { recursive: true, force: true });
    });
    it('strips package imports when packages are off', async () => {
        const output = await resolve();
        expect(output).not.toContain('import');
        expect(output).toContain('export const Toggle');
        expect(output).toContain('export const Note');
    });
    it('keeps package and package snippet imports when packages are on', async () => {
        setPackageImportOptions({
            packageNames: new Set(['recharts', '@acme/ui']),
            packageSnippets: new Set(['/snippets/toggle.jsx']),
        });
        const output = await resolve();
        expect(output).toContain('import {LineChart} from "recharts";');
        expect(output).toContain('import {Toggle} from "/snippets/toggle.jsx";');
        expect(output).not.toContain('export const Toggle');
        expect(output).toContain('export const Note');
    });
});
